'use strict';
// Review and hearts use separate local keys, so the progress earned in version 1 remains intact.
const REVIEW_KEY='javalingo-review-v1', SETTINGS_KEY='javalingo-settings-v1';
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
const reviewState=readLocal(REVIEW_KEY,{items:{},hearts:10,lastRegen:Date.now(),streak:0});
const settings=readLocal(SETTINGS_KEY,{theme:'light',language:'pt'});
if(!reviewState.items||typeof reviewState.items!=='object')reviewState.items={};
// Quem estava com o limite antigo cheio recebe as cinco vidas adicionais.
if(!reviewState.lifeLimitVersion){reviewState.hearts=Math.min(10,(Number(reviewState.hearts)||0)+5);reviewState.lifeLimitVersion=2}
reviewState.hearts=Math.max(0,Math.min(10,Number(reviewState.hearts)||0));
reviewState.lastRegen=Number(reviewState.lastRegen)||Date.now();
let reviewFilter={track:'all',status:'all',topic:'all',search:''};
const saveReview=()=>{try{localStorage.setItem(REVIEW_KEY,JSON.stringify(reviewState))}catch{}};
const saveSettings=()=>{try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings))}catch{}};
function refreshHearts(){let now=Date.now(),step=20*60*1000;if(reviewState.hearts>=10){reviewState.lastRegen=now;return}let count=Math.floor(Math.max(0,now-reviewState.lastRegen)/step);if(count){reviewState.hearts=Math.min(10,reviewState.hearts+count);reviewState.lastRegen=reviewState.hearts===10?now:reviewState.lastRegen+count*step;saveReview()}}
function updateHearts(){refreshHearts();let h=document.querySelector('#heartCount');if(h)h.textContent=reviewState.hearts;let box=document.querySelector('#heartStat');if(box){let minutes=Math.ceil((20*60*1000-(Date.now()-reviewState.lastRegen))/(60*1000));box.title=reviewState.hearts===10?(settings.language==='en'?'Lives full':'Vidas cheias'):(settings.language==='en'?`Next life in ${Math.max(1,minutes)} min`:`Próxima vida em ${Math.max(1,minutes)} min`);box.classList.toggle('empty',reviewState.hearts===0)}let badge=document.querySelector('#reviewBadge');if(badge){let pending=Object.values(reviewState.items).filter(x=>!x.resolved).length;badge.textContent=pending?pending:'';badge.hidden=!pending}}
function rememberMistake(v,answer,type='choice'){let current=reviewState.items[v.id]||{id:v.id,attempts:0,first:Date.now()};current.attempts++;current.last=Date.now();current.history=Array.isArray(current.history)?current.history:[];current.history.push({at:current.last,answer:String(answer||'').slice(0,900)});current.resolved=false;current.type=type;current.answer=String(answer||'').slice(0,900);current.correct=v.kind==='choice'?v.options[v.correct]:v.model;reviewState.items[v.id]=current;saveReview();updateHearts()}
function trackAnswer(v,index){if(index===v.correct){done(v.id);return}rememberMistake(v,v.options[index]);refreshHearts();reviewState.hearts=Math.max(0,reviewState.hearts-1);reviewState.streak=0;reviewState.lastRegen=reviewState.hearts===9?Date.now():reviewState.lastRegen;saveReview();updateHearts()}
function trackSelfReview(v){rememberMistake(v,codeAnswer,'code')}
function onPracticeDone(id){let item=reviewState.items[id];if(item){item.resolved=true;item.reviewed=Date.now()}reviewState.streak=(reviewState.streak||0)+1;if(reviewState.streak>=3){refreshHearts();reviewState.hearts=Math.min(10,reviewState.hearts+1);reviewState.streak=0;reviewState.lastRegen=Date.now();toast(settings.language==='en'?'Three correct practices: +1 life!':'Três práticas acertadas: +1 vida!')}saveReview();updateHearts()}
function renderReview(){const records=Object.values(reviewState.items).sort((a,b)=>b.last-a.last);const routeIds=[...new Set(records.map(x=>parseJavaPracticeId(x.id).trackId))].filter(id=>javaMegaNumber(id)||javaMainNumber(id));const options=[...TRACKS,...routeIds.map(findJavaTrack)].map(t=>`<option value="${t.id}" ${reviewFilter.track===t.id?'selected':''}>${esc(t.title)}</option>`).join('');const topics=reviewFilter.track==='all'?[]:findJavaTrack(reviewFilter.track)?.topics;const topicOptions=topics?topics.map((t,i)=>`<option value="${i}" ${reviewFilter.topic===String(i)?'selected':''}>${esc(t[0])}</option>`).join(''):'';const shown=records.filter(x=>{const {trackId,topicId}=parseJavaPracticeId(x.id);const t=findJavaTrack(trackId);if(!t||!t.topics[Number(topicId)])return false;if(reviewFilter.track!=='all'&&trackId!==reviewFilter.track)return false;if(reviewFilter.topic!=='all'&&topicId!==reviewFilter.topic)return false;if(reviewFilter.status==='open'&&x.resolved)return false;if(reviewFilter.status==='resolved'&&!x.resolved)return false;const hay=[t.title,t.topics[Number(topicId)][0],x.answer,x.correct].join(' ').toLocaleLowerCase();return hay.includes(reviewFilter.search.toLocaleLowerCase())});const open=records.filter(x=>!x.resolved).length;app.innerHTML=`<section class="review-intro"><div><span class="eyebrow">SEU CADERNO DE REVISÃO</span><h1 class="page-title">Aprenda com cada tentativa.</h1><p>Veja onde você errou, entenda o conceito e volte ao exercício quando estiver pronta.</p></div><div class="review-count"><strong>${open}</strong><span>para revisar</span></div></section><div class="review-filters"><label>Trilha<select id="reviewTrack"><option value="all">Todas as trilhas</option>${options}</select></label><label>Tópico<select id="reviewTopic" ${reviewFilter.track==='all'?'disabled':''}><option value="all">Todos os tópicos</option>${topicOptions}</select></label><label>Estado<select id="reviewStatus"><option value="all" ${reviewFilter.status==='all'?'selected':''}>Todos</option><option value="open" ${reviewFilter.status==='open'?'selected':''}>Para revisar</option><option value="resolved" ${reviewFilter.status==='resolved'?'selected':''}>Revisados</option></select></label><label>Buscar<input id="reviewSearch" type="search" value="${esc(reviewFilter.search)}" placeholder="Conceito ou resposta"></label></div>${records.length===0?`<div class="review-empty">${icon('repeat')}<h2>Seu caderno está pronto</h2><p>As respostas incorretas e os códigos que você marcar para revisão aparecerão aqui.</p><button class="button button-primary" data-action="back-home">Explorar trilhas ${icon('arrow')}</button></div>`:shown.length===0?`<div class="review-empty"><h2>Nada com esses filtros</h2><p>Tente outra trilha, tópico ou palavra.</p></div>`:`<div class="review-list">${shown.map(x=>{let {trackId:tr,topicId:ti,questionId:q}=parseJavaPracticeId(x.id),t=findJavaTrack(tr),v=getQuestion(t,Number(ti),Number(q));return `<article class="review-card ${x.resolved?'resolved':''}"><div class="review-card-head"><span class="review-tag">${esc(t.title)} · ${esc(v.t[0])}</span><span class="review-status">${x.resolved?'Revisado':'Para revisar'}</span></div><h2>${esc(v.prompt)}</h2><div class="review-answers"><p><strong>Sua tentativa:</strong> <code>${esc(x.answer||'Sem resposta escrita')}</code></p><p><strong>Modelo / resposta:</strong> <code>${esc(x.correct)}</code></p></div><p><strong>Por quê?</strong> ${esc(v.q===2?v.t[5]:v.t[1])}</p><p class="review-analogy"><strong>Analogia:</strong> ${esc(v.t[2])}</p>${x.history&&x.history.length>1?`<details class="review-history"><summary>Ver todas as ${x.history.length} tentativas</summary><ol>${x.history.map(h=>`<li><time>${new Date(h.at).toLocaleString(settings.language==='en'?'en-US':'pt-BR')}</time> · <code>${esc(h.answer||'Sem resposta')}</code></li>`).join('')}</ol></details>`:''}<div class="review-card-foot"><span>${x.attempts} ${x.attempts===1?'tentativa registrada':'tentativas registradas'} · ${new Date(x.last).toLocaleDateString(settings.language==='en'?'en-US':'pt-BR')}</span><button class="button button-secondary" data-retry-id="${esc(x.id)}">Refazer exercício ${icon('arrow')}</button></div></article>`}).join('')}</div>`}`;applyLanguage()}
function handleReviewClick(b){if(b.dataset.action==='jump-code'){lesson.q=4;selected=null;answered=false;codeAnswer='';renderLesson();window.scrollTo(0,0);return true}if(b.dataset.retryId){const {trackId:tr,topicId:ti,questionId:q}=parseJavaPracticeId(b.dataset.retryId);track=findJavaTrack(tr);if(!track)return true;startLesson(Number(ti));lesson.q=Number(q);selected=null;answered=false;codeAnswer='';render();window.scrollTo(0,0);return true}return false}
app.addEventListener('change',e=>{if(e.target.id==='reviewTrack'){reviewFilter.track=e.target.value;reviewFilter.topic='all';renderReview()}if(e.target.id==='reviewTopic'){reviewFilter.topic=e.target.value;renderReview()}if(e.target.id==='reviewStatus'){reviewFilter.status=e.target.value;renderReview()}});
app.addEventListener('input',e=>{if(e.target.id==='reviewSearch'){reviewFilter.search=e.target.value;const pos=e.target.selectionStart;renderReview();const target=$('#reviewSearch');target.focus();target.setSelectionRange(pos,pos)}});
function setTheme(theme){settings.theme=theme;document.documentElement.dataset.theme=theme;saveSettings();let b=$('#themeToggle');if(b){b.innerHTML=icon(theme==='dark'?'sun':'moon');b.setAttribute('aria-label',settings.language==='en'?(theme==='dark'?'Switch to light theme':'Switch to dark theme'):(theme==='dark'?'Ativar modo claro':'Ativar modo escuro'));b.title=settings.language==='en'?(theme==='dark'?'Light theme':'Dark theme'):(theme==='dark'?'Modo claro':'Modo escuro')}}
function setLanguage(lang){if(lang==='en'&&lab.title==='Minha primeira interface')lab.title='My first interface';if(lang==='pt'&&lab.title==='My first interface')lab.title='Minha primeira interface';settings.language=lang;document.documentElement.lang=lang==='en'?'en':'pt-BR';saveSettings();$('#languageToggle').textContent=lang==='en'?'EN':'PT';$('#languageToggle').setAttribute('aria-label',lang==='en'?'Mudar idioma para português':'Change language to English');render();setTheme(settings.theme)}
$('#themeToggle').addEventListener('click',()=>setTheme(settings.theme==='dark'?'light':'dark'));
$('#languageToggle').addEventListener('click',()=>setLanguage(settings.language==='en'?'pt':'en'));
setTheme(settings.theme);setInterval(updateHearts,60000);
