getQuestion=function(tr,ti,q){if(settings.language!=='en')return ptQuestion(tr,ti,q);const clone={id:tr.id,topics:tr.topics.map((t,i)=>{const x=EN_TOPIC_TEXT[tr.id][i];return [x[0],x[1],x[2],t[3],t[4],x[3],x[4],t[7],t[8]]})};let v=ptQuestion(clone,ti,q),t=v.t;const prompts=[`What is ${t[0]}?`,`Which snippet demonstrates ${t[0]}?`,`What is wrong with this snippet?`,`Which concept helps you ${t[6]}?`,`Write an example: ${t[6]}.`,`Fix the snippet about ${t[0]}.`,`From memory: apply ${t[0]} to your own situation.`,`Independent challenge: write another way to ${t[6]}.`,`Debug and document the error in ${t[0]}.`,`Final challenge: use ${t[0]} in a real situation.`];const details=['Choose the description matching the concept.','Study the syntax before choosing.','Find the main cause of this error.','Choose the most direct concept for the task.','Type a Java snippet below, then compare it with a model.','Rewrite the snippet to fix the issue. More than one solution may be valid.',`Write an example showing ${t[7]}, then compare the principle with the model.`,'Use different names and add a Java comment explaining your choice.','Write the correction and a // comment explaining the original mistake.',`Imagine a small program needing ${t[7]}. Write a small snippet and comment on how you would test it.`];v.prompt=prompts[q];v.description=details[q];return v};
feedbackHTML=function(v){if(settings.language!=='en'){let html=ptFeedback(v);return v.kind==='choice'&&selected!==v.correct?html.replace('</section>','<p class="life-feedback">Você perdeu 1 vida. Esta questão foi salva em Revisar erros para estudar depois.</p></section>'):html;}if(v.kind==='choice'){let right=selected===v.correct;return `<section class="feedback ${right?'':'wrong'}" role="status"><h3>${right?'Exactly right!':'Let’s work through it'}</h3><p>${right?esc(v.t[1]):`You chose “${esc(v.options[selected])}”. The correct answer is <strong>${esc(v.options[v.correct])}</strong>. ${esc(v.q===2?v.t[5]:v.t[1])}`}</p>${v.q===1||v.q===2?`<p><strong>Example:</strong> <code>${esc(v.t[3])}</code></p>`:''}<p class="analogy"><strong>Think of it this way:</strong> ${esc(v.t[2])}</p>${right?'':'<p class="life-feedback">You lost 1 life. This question was saved in Review mistakes.</p>'}</section>`}let clues=[];if(!codeAnswer.trim())clues.push('You have not written an example yet. Adapt the model with your own names.');else{if(!codeAnswer.includes(v.t[8]))clues.push('Check whether your solution shows the main syntax or an equivalent approach.');if((codeAnswer.match(/\{/g)||[]).length!==(codeAnswer.match(/\}/g)||[]).length)clues.push('Check that every opening brace has a closing brace.');if(v.q===5||v.q===8)clues.push(v.t[5]);if(!clues.length)clues.push('You included the main element. Also review types, imports and complete syntax in VS Code.')}return `<section class="feedback" role="status"><h3>Compare your solution</h3><p><strong>One possible model:</strong></p><pre class="model-code">${esc(v.model)}</pre><p>${esc(clues.join(' '))}</p><p><strong>Why it works:</strong> ${esc(v.t[1])}</p><p class="analogy"><strong>Think of it this way:</strong> ${esc(v.t[2])}</p><p class="editor-caption">This is guided review, not Java compilation. A different solution may also be correct.</p><div class="exercise-actions"><button class="button button-secondary" data-action="self-correct">I solved it</button><button class="button button-plain" data-action="self-review">Review later</button></div></section>`};
