function localizeText(raw){const before=raw.trim();if(!before)return raw;let result=settings.language==='en'?(UI_EN[before]||before):(UI_PT[before]||before);
 if(settings.language==='en')result=result.replace(/^(\d+) de 100 práticas concluídas · 10 tópicos$/,(_,n)=>`${n} of 100 practices completed · 10 topics`).replace(/^(\d+) de 100 práticas concluídas$/,(_,n)=>`${n} of 100 practices completed`).replace(/^(\d+) de 10 práticas · escolha e código$/,(_,n)=>`${n} of 10 practices · choices and coding`).replace(/^Você chegou ao fim das 10 práticas\. Pode refazê-las quando quiser\.$/,'You reached the end of 10 practices. You can revisit them anytime.').replace(/^Texto · (.+)$/,(_,x)=>`Text · ${UI_EN[x]||x}`).replace(/^([^:]+): (.+)$/,(_,x,y)=>`${UI_EN[x]||x}: ${y}`);
 else result=result.replace(/^(\d+) of 100 practices completed · 10 topics$/,(_,n)=>`${n} de 100 práticas concluídas · 10 tópicos`).replace(/^(\d+) of 100 practices completed$/,(_,n)=>`${n} de 100 práticas concluídas`).replace(/^(\d+) of 10 practices · choices and coding$/,(_,n)=>`${n} de 10 práticas · escolha e código`);
 if(settings.language==='en'){for(const tr of TRACKS)result=result.replaceAll(tr.title,EN_TRACK_NAMES[tr.id]);result=result.replace(' · Escolha a resposta',' · Choose an answer').replace(' · Escreva código',' · Write code')}else{for(const tr of TRACKS)result=result.replaceAll(EN_TRACK_NAMES[tr.id],tr.title);result=result.replace(' · Choose an answer',' · Escolha a resposta').replace(' · Write code',' · Escreva código')}if(track&&(javaMegaNumber(track.id)||javaMainNumber(track.id)))result=settings.language==='en'?result.replaceAll(track.title,track.enTitle):result.replaceAll(track.enTitle,track.title);return raw.replace(before,result)}
function applyLanguage(){document.documentElement.lang=settings.language==='en'?'en':'pt-BR';for(const root of [document.querySelector('.sidebar'),document.querySelector('.topbar'),app,document.querySelector('.bottom-nav')]){if(!root)continue;const visit=node=>{if(node.nodeType===3){const parent=node.parentElement;if(parent&&/^(PRE|CODE|TEXTAREA|SCRIPT|STYLE)$/i.test(parent.tagName))return;node.nodeValue=localizeText(node.nodeValue);return}if(node.nodeType!==1)return;if(/^(PRE|CODE|TEXTAREA|SCRIPT|STYLE)$/i.test(node.tagName))return;for(const child of node.childNodes)visit(child)};visit(root)}for(const node of document.querySelectorAll('[placeholder]')){if(node.id==='reviewSearch')node.placeholder=settings.language==='en'?'Concept or answer':'Conceito ou resposta';if(node.id==='exerciseEditor')node.placeholder=settings.language==='en'?'// Write Java here...':'// Escreva seu trecho de Java aqui...'}updateHearts()}
